import sys
from collections import defaultdict

MOD = 10**9 + 7

def count_decreasing_paths(matrix, n):
    dp = [[0] * n for _ in range(n)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n

    for num in range(1, 101):
        positions = []
        for i in range(n):
            for j in range(n):
                if matrix[i][j] == num:
                    positions.append((i, j))
                    dp[i][j] = 1

        for x, y in positions:
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and matrix[nx][ny] > matrix[x][y]:
                    dp[nx][ny] = (dp[nx][ny] + dp[x][y]) % MOD

    return sum(sum(row) for row in dp) % MOD

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    index += 1
    matrix = []
    for _ in range(n):
        row = list(map(int, input[index:index+n]))
        matrix.append(row)
        index += n
    result = count_decreasing_paths(matrix, n)
    print(result)

if __name__ == "__main__":
    main()
